import torch
from torch import nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source (inline) implementing fp16 GEMM
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef TILE_SIZE
#define TILE_SIZE 16
#endif

// ---------------------------------------------------------------
// Kernel: C = A * B   (A: MxK, B: KxN, C: MxN)
// All tensors are fp16, accumulation in fp32.
// ---------------------------------------------------------------
__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int K, int N) {
    // thread identifiers
    const int row = blockIdx.y * TILE_SIZE + threadIdx.y; // M dimension
    const int col = blockIdx.x * TILE_SIZE + threadIdx.x; // N dimension

    // shared memory tiles
    __shared__ __half As[TILE_SIZE][TILE_SIZE];
    __shared__ __half Bs[TILE_SIZE][TILE_SIZE];

    float acc = 0.0f; // accumulator in fp32

    // loop over K dimension tiles
    const int tiles = (K + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < tiles; ++t) {
        // global indices for the elements to load
        int a_row = row;
        int a_col = t * TILE_SIZE + threadIdx.x;

        int b_row = t * TILE_SIZE + threadIdx.y;
        int b_col = col;

        // load A tile
        if (a_row < M && a_col < K) {
            As[threadIdx.y][threadIdx.x] = A[a_row * K + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // load B tile
        if (b_row < K && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // compute partial product for this tile
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; ++i) {
            acc += __half2float(As[threadIdx.y][i]) *
                   __half2float(Bs[i][threadIdx.x]);
        }

        __syncthreads();
    }

    // write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------
// C++ wrapper
// ---------------------------------------------------------------
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    // sanity checks
    TORCH_CHECK(A.dtype() == torch::kHalf, "A must be fp16");
    TORCH_CHECK(B.dtype() == torch::kHalf, "B must be fp16");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "inputs must be contiguous");

    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t K2 = B.size(0);
    const int64_t N = B.size(1);
    TORCH_CHECK(K == K2, "Incompatible inner dimensions");

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(A.device())
                       .layout(torch::kStrided);
    torch::Tensor C = torch::empty({M, N}, options);

    // launch configuration
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid( (N + TILE_SIZE - 1) / TILE_SIZE,
               (M + TILE_SIZE - 1) / TILE_SIZE );

    const int total_threads = block.x * block.y;
    // shared memory size (two tiles)
    const size_t shmem_bytes = 2 * TILE_SIZE * TILE_SIZE * sizeof(__half);

    // get current CUDA stream from PyTorch
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    matmul_fp16_kernel<<<grid, block, shmem_bytes, stream>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        static_cast<int>(M),
        static_cast<int>(K),
        static_cast<int>(N));

    // check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(
            std::string("CUDA kernel launch failed: ") + cudaGetErrorString(err));
    }

    return C;
}

// ---------------------------------------------------------------
// PyBind
// ---------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "FP16 matrix multiplication (custom kernel)");
}
'''

# Compile the inline extension
matmul_ext = load_inline(name='matmul_fp16_ext',
                         cpp_sources='',
                         cuda_sources=src,
                         functions=['matmul_fp16'],
                         verbose=False)

# ----------------------------------------------------------------------
# Python model that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model, but uses a custom
    fp16 GEMM kernel compiled for A100 (CC 8.0).
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # ensure inputs are fp16 and on CUDA
        if A.dtype != torch.float16:
            A = A.to(dtype=torch.float16)
        if B.dtype != torch.float16:
            B = B.to(dtype=torch.float16)
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        # call the custom kernel
        C = matmul_ext.matmul_fp16(A, B)
        return C

# ----------------------------------------------------------------------
# Helper functions mirroring the reference script
# ----------------------------------------------------------------------
def get_inputs():
    M, K, N = 8205, 2949, 5921
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(K, N, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special init needed

# ----------------------------------------------------------------------
# Simple sanity test (executed only when run directly)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    A, B = get_inputs()
    model = ModelNew().cuda()
    C = model(A, B)
    # compare with torch.matmul for verification
    C_ref = torch.matmul(A, B)
    max_err = (C.float() - C_ref).abs().max()
    print(f"max absolute error vs torch.matmul: {max_err.item()}")
